import { ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, numberAttribute } from '@angular/core';

@Component({
    selector: 'mrd-error',
    templateUrl: './mrd-error.component.html',
    styleUrls: ['./mrd-error.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdErrorComponent {

  @Input({transform: numberAttribute}) public ellipsis: number;

  private _error: string = '';

  public set error(value: string) {
    this._error = value;
    this.cdr.detectChanges();
  }

  public get error(): string {
    return this._error;
  }

  constructor(
    private cdr: ChangeDetectorRef
  ) { }

  ngAfterViewInit(): void {
    if (this.ellipsis !== undefined && Number.isNaN(this.ellipsis)) {
      this.ellipsis = 1;
    }
    this.cdr.detectChanges();
  }
}
