import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Host, Input, Output, ViewChild, booleanAttribute } from '@angular/core';
import { MrdSelectComponent } from '../mrd-select/mrd-select.component';

@Component({
    selector: 'mrd-select-option',
    templateUrl: './mrd-select-option.component.html',
    styleUrls: ['./mrd-select-option.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdSelectOptionComponent implements AfterViewInit {

  @ViewChild('optionValue') public optionValue: ElementRef<HTMLElement> | undefined;

  @Input() public value: any;

  @Input({transform: booleanAttribute}) public noCheckbox: boolean = false;
  
  @Input({transform: booleanAttribute}) public disabled: boolean = false;

  @Output() public optionClicked: EventEmitter<MrdSelectOptionChange> = new EventEmitter<MrdSelectOptionChange>();

  public optionLabel: string;

  public _selected: boolean = false;
  public _filtered: boolean = false;
  public _focused: boolean = false;

  public multiple: boolean = false;

  constructor(
    private elementRef: ElementRef,
    @Host() private select: MrdSelectComponent,
    private cdr: ChangeDetectorRef
  ) {}

  ngAfterViewInit(): void {
    this.multiple = this.select.multiple;
    if (this.optionValue) {
      this.optionLabel = this.optionValue.nativeElement.innerText;
    }
    this.cdr.detectChanges();
  }

  public optionClick(): void {
    this.optionClicked.emit({key: this.value, value: this.optionValue?.nativeElement.innerText || '', option: this, checked: !this.selected});
    this.cdr.markForCheck();
  }

  public set selected(value: boolean) {
    this._selected = value;
    this.cdr.detectChanges();
    this.cdr.markForCheck();
  }

  public get selected(): boolean {
    return this._selected;
  }

  public set filtered(value: boolean) {
    this._filtered = value;
    this.cdr.detectChanges();
    this.cdr.markForCheck();
  }

  public get filtered(): boolean {
    return this._filtered;
  }

  public set focused(value: boolean) {
    this._focused = value;
    this.cdr.detectChanges();
    this.cdr.markForCheck();
  }

  public get focused(): boolean {
    return this._focused;
  }
}


export interface MrdSelectOptionChange {
  key: any;
  value: string;
  option: MrdSelectOptionComponent;
  checked?: boolean;
}
