import { AfterViewInit, booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, Output, ViewChild } from '@angular/core';
import { MrdConfigModel } from '../../../../common/model/config.model';
import { colorAttribute, colorThemeAttribute } from '../../../../common/transforms/color-transform';
import { ColorUtil } from '../../../../common/util/color.util';
import { ConfigUtil } from '../../../../common/util/config.util';

@Component({
    selector: 'mrd-chip',
    templateUrl: './mrd-chip.component.html',
    styleUrls: ['./mrd-chip.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdChipComponent implements AfterViewInit {

  @ViewChild('chipText') public chipText: ElementRef<HTMLElement> | undefined;

  @Input({transform: booleanAttribute}) public primary: boolean = false;
  @Input({transform: booleanAttribute}) public accent: boolean = false;
  @Input({transform: booleanAttribute}) public warn: boolean = false;

   @Input({transform: colorThemeAttribute}) public set color(value: string) {
      this._color = value;
   }
   public get color() {
      return this._color;
   }
   private _color: string;

   @Input({transform: colorAttribute}) public set backgroundColor(value: string) {
      this._backgroundColor = value;
   }
    public get backgroundColor() {
        return this._backgroundColor;
    }
    private _backgroundColor: string;

  @Input({transform: booleanAttribute}) public clickable: boolean = false;
  
  @Input({transform: booleanAttribute}) public closeable: boolean = true;

  @Input('prefixIcon') prefixIcon: string;
  @Input('suffixIcon') suffixIcon: string;

  @Input({transform: booleanAttribute}) public set disabled(value: boolean) {
    this._disabled = value;
    this.backgroundColor = value ? '#ced9dd' : this.backgroundColor;
    this.color = value ? '#a6a6a6' : this.color;
  }
  public get disabled() {
    return this._disabled;
  }
  private _disabled: boolean = false;

  @Input({transform: colorAttribute}) public closeIconColor: string;
  @Input({transform: colorAttribute}) public closeIconCrossColor: string;

  @Output() close: EventEmitter<void> = new EventEmitter<void>();

  /**
     * Die Konfiguration des Mrd-Buttons.
     *
     * @private
     * @type {MrdConfigModel}
     * @memberof MrdButtonComponent
     */
    private _config: MrdConfigModel = ConfigUtil.getConfig();

  public chipTextValue: string;

  constructor(
    private cdr: ChangeDetectorRef
  ) {}

  ngAfterViewInit(): void {
    if ((this.primary || this.accent || this.warn) && !this.backgroundColor) {
      this.backgroundColor = this._config.baseColors[this.primary ? 'primary' : this.accent ? 'accent' : 'warn'] as string; 
    } else if (!this.backgroundColor) {
      this.backgroundColor = '#ced9dd';
    }
    if (!this.color || !ColorUtil.isHexColor(this.color)) {
      this.color = ColorUtil.shouldTextBeDark(this.backgroundColor) ? '#000000' : '#ffffff';
    }
    let iconBgDark: boolean = ColorUtil.shouldTextBeDark(this.backgroundColor)
    let customIconBg: boolean = true;
    if (!this.closeIconColor) {
      this.closeIconColor = iconBgDark ? '#606367' : '#ffffff';
      customIconBg = false;
    }
    this.closeIconCrossColor = customIconBg ? ColorUtil.shouldTextBeDark(this.closeIconColor) ? '#000000' : '#ffffff' : iconBgDark ? '#ffffff' : '#000000';

    if (this.chipText) {
      this.chipTextValue = this.chipText.nativeElement.innerText;
    }

    this.cdr.detectChanges();
  }

  public closeClicked(event: MouseEvent): void {
    event.stopPropagation();
    event.stopImmediatePropagation();
    if (!this.disabled) {
      this.close.emit();
    }
  }
}
