import { AfterViewChecked, AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, EventEmitter, Input, Output, ViewChild, booleanAttribute } from '@angular/core';
import { AccessableFormControl, Util } from 'mrd-core';
import { sizeAttribute } from '../../../../common/transforms/size-transform';
import { colorAttribute, colorThemeAttribute } from '../../../../common/transforms/color-transform';
import { MrdBaseColorTheme, MrdConfigModel } from '../../../../common/model/config.model';
import { ConfigUtil } from '../../../../common/util/config.util';
import * as _ from 'underscore';

@Component({
    selector: 'mrd-checkbox',
    templateUrl: './mrd-checkbox.component.html',
    styleUrls: ['./mrd-checkbox.component.scss'],
    host: {
        "[style.max-width]": "fitContent ? 'fit-content' : '100%'",
    },
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdCheckboxComponent implements AfterViewInit, AfterViewChecked {

  @ViewChild('checkboxlabel') public label: ElementRef<HTMLElement>;

  @Input('mrdFormControl') public formControl: AccessableFormControl;

  // @Input({transform: booleanAttribute}) public fill: boolean = false;
  // @Input({transform: booleanAttribute}) public outline: boolean = false;
  @Input({transform: booleanAttribute}) public rounded: boolean = false;

  // @Input({transform: booleanAttribute}) public primary: boolean = false;
  // @Input({transform: booleanAttribute}) public accent: boolean = false;
  // @Input({transform: booleanAttribute}) public warn: boolean = false;

  @Input({transform: colorAttribute}) public color: string = '#000000';
  @Input({transform: colorAttribute}) public colorHover: string = '#000000';
  @Input({transform: colorAttribute}) public colorChecked: string = '#000000';
  @Input({transform: colorAttribute}) public colorCheckedHover: string = '#000000';
  @Input({transform: colorAttribute}) public bgColor: string = 'transparent';
  @Input({transform: colorAttribute}) public bgColorHover: string = 'transparent';
  @Input({transform: colorAttribute}) public bgColorChecked: string = 'transparent';
  @Input({transform: colorAttribute}) public bgColorCheckedHover: string = 'transparent'; 
  @Input() public border: string = 'none';
  @Input() public borderHover: string = 'none';
  @Input() public borderChecked: string = 'none';
  @Input() public borderCheckedHover: string = 'none';

  @Input({transform: booleanAttribute}) public checked: boolean = false;
  @Input({transform: booleanAttribute}) public disabled: boolean = false;
  @Input({transform: booleanAttribute}) public customIcons: boolean = false;
  @Input({transform: booleanAttribute}) public customHoverIcons: boolean = false;

  @Input({transform: sizeAttribute}) public checkboxSize: string = '16px';
  @Input({transform: sizeAttribute}) public checkboxHeight: string;
  @Input({transform: sizeAttribute}) public checkboxWidth: string;

  @Input({alias: 'single-line', transform: booleanAttribute}) public singleLine: boolean = false;
  @Input({alias: 'fit-content', transform: booleanAttribute}) public fitContent: boolean = false;
  @Input({transform: booleanAttribute}) public ellipsis: boolean = false;

  @Input({transform: booleanAttribute}) public tooltip: boolean = false;
  @Input({transform: booleanAttribute}) public tooltipIfTruncated: boolean = false;
  @Input() public set tooltipText(value: string) {
    if (Util.isDefined(value)) {
      this.customTooltipText = true;
      this._tooltipText = value;
    } else if (Util.isDefined(this.label)) {
      this._tooltipText = this.label.nativeElement.innerText;
    }
  }
  public get tooltipText(): string {
    return this._tooltipText;
  }
  private _tooltipText: string;
  private customTooltipText: boolean = false;
  @Input() public tooltipPosition: 'top' | 'bottom' | 'left' | 'right' = 'bottom';
  @Input({transform: booleanAttribute}) public tooltipDisabled: boolean = false;

  @Output() public checkedChange: EventEmitter<boolean> = new EventEmitter<boolean>();

  private config: MrdConfigModel = ConfigUtil.getConfig();

  constructor(
    private cdr: ChangeDetectorRef
  ) { }

  ngAfterViewInit(): void {
    if (Util.isDefined(this.formControl) && Util.isDefined(this.formControl.value)) {
      this.checked = !!this.formControl.value;
    }
    if (this.tooltipIfTruncated) {
      this.tooltip = true;
    }
    if (this.tooltip && !Util.isDefined(this.tooltipText)) {
      this._tooltipText = this.label.nativeElement.innerText;
    }
    if (!Util.isDefined(this.checkboxHeight)) {
      this.checkboxHeight = this.checkboxSize;
    }
    if (!Util.isDefined(this.checkboxWidth)) {
      this.checkboxWidth = this.checkboxSize;
    }

    this.cdr.detectChanges();
    // ['checkbox', 'fill', 'selected', 'primary', 'text'];
    // ['checkbox', 'selected', 'primary', 'text'];
    // ['baseColor', 'primary'];
    // if (this.primary) {
    //   this.color = _.isObject(this.config.baseColors.primary) ? (this.config.baseColors.primary as MrdBaseColorTheme).text : this.config.baseColors.primary as string;
    // } else if (this.accent) {
    //   this.color = this.config.accentColor;
    // } else if (this.warn) {
    //   this.color = this.config.warnColor;
    // }
  }

  ngAfterViewChecked(): void {
    if (this.tooltip && Util.isDefined(this.label) && !this.customTooltipText && (!Util.isDefined(this.tooltipText) || this.tooltipText !== this.label.nativeElement.innerText)) {
      this._tooltipText = this.label.nativeElement.innerText;
    }
  }

  // private initBaseStyle(): void {

  // }

  public toggle(): void {
    if (this.disabled || (Util.isDefined(this.formControl) && this.formControl.disabled)) {
      return;
    }
    this.checked = !this.checked;
    if (Util.isDefined(this.formControl)) {
      this.formControl.setValue(this.checked);
    }
    this.checkedChange.emit(this.checked);
    this.cdr.detectChanges();
  }
}
