import { booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, OnInit, Output } from '@angular/core';
import { colorAttribute } from './../../../../common/transforms/color-transform';
import { sizeAttribute } from './../../../../common/transforms/size-transform';
import { MrdToggleSwitchState } from '../../common/enum/mrd-toggle-switch-state.enum';
import { MrdConfigModel } from './../../../../common/model/config.model';
import { ConfigUtil } from './../../../../common/util/config.util';

@Component({
    selector: 'mrd-toggle-switch',
    templateUrl: './mrd-toggle-switch.component.html',
    styleUrls: ['./mrd-toggle-switch.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdToggleSwitchComponent implements OnInit {

  public MrdToggleSwitchState = MrdToggleSwitchState;

  @Input({transform: colorAttribute}) bgColor: string;

  @Input({transform: colorAttribute}) bgNeutralColor: string;

  @Input({transform: colorAttribute}) knobColor: string;

  @Input({transform: colorAttribute}) knobNeutralColor: string;

  @Input({transform: sizeAttribute}) width: string;

  @Input({transform: sizeAttribute}) height: string;

  @Input({transform: colorAttribute}) bgDisabledColor: string;

  @Input({transform: colorAttribute}) knobDisabledColor: string;

  @Input({transform: booleanAttribute}) disabled: boolean = false;

  @Input() set state(value: MrdToggleSwitchState) {
    if(this._state !== value) {
      this._state = value;
      this.stateChange.emit(this._state);
    }
    this.cdr.detectChanges();
  }
  public get state(): MrdToggleSwitchState {
    return this._state;
  } 
  
  private _state: MrdToggleSwitchState = MrdToggleSwitchState.NEUTRAL;

  @Output() stateChange: EventEmitter<MrdToggleSwitchState> = new EventEmitter<MrdToggleSwitchState>();

  private _config: MrdConfigModel = ConfigUtil.getConfig();

  constructor(
    private cdr: ChangeDetectorRef
  ) { }

  ngOnInit(): void {
    if(!this.width) {
      this.width = this._config.toggleSwitch.width;
    }
    if(!this.height) {
      this.height = this._config.toggleSwitch.height;
    }
    if(!this.bgColor) {
      this.bgColor = this._config.toggleSwitch.bgColor;
    }
    if(!this.bgNeutralColor) {
      this.bgNeutralColor = this._config.toggleSwitch.bgNeutralColor;
    }
    if(!this.knobColor) {
      this.knobColor = this._config.toggleSwitch.knobColor;
    }
    if(!this.knobNeutralColor) {
      this.knobNeutralColor = this._config.toggleSwitch.knobNeutralColor;
    }
    if(!this.bgDisabledColor) {
      this.bgDisabledColor = this._config.toggleSwitch.bgDisabledColor;
    }
    if(!this.knobDisabledColor) {
      this.knobDisabledColor = this._config.toggleSwitch.knobDisabledColor;
    }
    this.cdr.detectChanges();
  }

  public toggle(event: PointerEvent, state?: MrdToggleSwitchState): void {
    event.stopPropagation();
    if(!this.disabled) {
      if(state) {
        this.state = state;
      } else {
        this.state = this.state === MrdToggleSwitchState.LEFT ? MrdToggleSwitchState.RIGHT : MrdToggleSwitchState.LEFT;
      }
    }
    this.cdr.detectChanges();
  }
}
