import { booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, Input, numberAttribute } from '@angular/core';
import { Util } from 'mrd-core';
import * as _ from 'underscore';

@Component({
    selector: 'mrd-decimal',
    host: {
        '[style.align-items]': 'textEnd ? "flex-end" : centered ? "center" : "flex-start"',
        '[style.background-color]': 'backgroundColor',
        '[style.color]': 'color'
    },
    templateUrl: './mrd-decimal.component.html',
    styleUrls: ['./mrd-decimal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdDecimalComponent {

  @Input() public set backgroundColor(value: string) {
    this._backgroundColor = value;
    this.cdr.markForCheck();
  };
  public get backgroundColor(): string {
    return this._backgroundColor;
  }
  private _backgroundColor: string;

  @Input() public set color(value: string) {
    this._color = value;
    this.cdr.markForCheck();
  }
  public get color(): string {
    return this._color;
  }
  private _color: string;

  @Input({alias: 'text-end', transform: booleanAttribute}) public set textEnd(value: boolean) {
    this._textEnd = value;
    this.cdr.markForCheck();
  }
  public get textEnd(): boolean {
    return this._textEnd;
  }
  private _textEnd: boolean = false;

  @Input({alias: 'text-centered', transform: booleanAttribute}) public set centered(value: boolean) {
    this._centered = value;
    this.cdr.markForCheck();
  }
  public get centered(): boolean {
    return this._centered;
  }
  private _centered: boolean = false

  @Input() public set value(value: number) {
    this._value = value;
    this.generateValueString();
  }
  public get value(): number {
    return this._value;
  }
  private _value: number;

  @Input({transform: numberAttribute}) public set maxDigits(value: number) {
    this._maxDigits = value;
    this.generateValueString();
  }
  public get maxDigits(): number {
    return this._maxDigits;
  }
  private _maxDigits: number = 99;

  @Input({transform: numberAttribute}) public set minDigits(value: number) {
    this._minDigits = value;
    this.generateValueString();
  }
  public get minDigits(): number {
    return this._minDigits;
  }
  private _minDigits: number = 0;

  @Input({transform: booleanAttribute}) public set tausendertrennpunkt(value: boolean) {
    this._tausendertrennpunkt = value;
    this.generateValueString();
  }
  public get tausendertrennpunkt(): boolean {
    return this._tausendertrennpunkt;
  }
  private _tausendertrennpunkt: boolean = false;

  @Input({transform: booleanAttribute}) public smallDigits: boolean = false;

  private decimalString: string = '';
  private digitsString: string = '';

  constructor(
    private cdr: ChangeDetectorRef
  ) { }

  public get decimalValue(): string {
    return `${this.decimalString}${Util.isDefinedNotEmptyOrZero(this.digitsString) ? ',' : ''}`;
  }

  public get digitsValue(): string {
    return this.digitsString;
  }

  private generateValueString(): void {
    let valueString = '';
    if (Util.isDefined(this.value) && _.isNumber(this.value) && !_.isNaN(this.value)) {
      valueString = this.value.toLocaleString('de-DE', {minimumFractionDigits: this.minDigits, maximumFractionDigits: this.maxDigits});

      if (!this.tausendertrennpunkt) {
        valueString = valueString.replace(/\./g, '');
      }
      this.decimalString = Util.isDefinedNotEmptyOrZero(valueString, true, ',').split(',')[0];
      this.digitsString = Util.isDefinedNotEmptyOrZero(valueString, true, ',').split(',')[1];
    } else {
      this.decimalString = Util.isDefined(this.value) ? this.value.toString() : '';
      this.digitsString = '';
    }

    this.cdr.markForCheck();
  }
}
