import { booleanAttribute, Directive, ElementRef, HostListener, Input, OnChanges, SimpleChanges } from '@angular/core';

/***
 * Limitiert die Eingabe einer Zahl auf x (default 2) Nachkommastellen.
 */
@Directive({
    selector: '[decimalNumber]',
    standalone: false
})
export class DecimalNumberDirective implements OnChanges {

  @Input({transform: booleanAttribute}) public decimalNumber: boolean = true;

  @Input() public nachkommastellen: number = 2;

  private regex: RegExp = new RegExp(/^\d*\,?\d{0,2}$/g);
  private specialKeys: Array<string> = ['Backspace', 'Tab', 'End', 'Home', '-', 'ArrowLeft', 'ArrowRight', 'Del', 'Delete'];
  constructor(private el: ElementRef) {
    this.regex = new RegExp(`^\\d*\\,?\\d{0,${this.nachkommastellen}}$`);
  }
  @HostListener('keydown', ['$event'])
  onKeyDown(event: KeyboardEvent) {
    if (!this.decimalNumber) {
      return;
    }
    // Allow Backspace, tab, end, and home keys
    if (this.specialKeys.indexOf(event.key) !== -1) {
      return;
    }
    let current: string = this.el.nativeElement.value;
    const position = this.el.nativeElement.selectionStart;
    const next: string = [current.slice(0, position), event.key == 'Decimal' ? ',' : event.key, current.slice(position)].join('');

    if (next && !String(next).match(this.regex)) {
      event.preventDefault();
    }
  }

  public ngOnChanges(changes: SimpleChanges): void {
    this.regex = new RegExp(`^\\d*\\,?\\d{0,${this.nachkommastellen}}$`);
  }
}