import { booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, Input } from '@angular/core';
import { BasePushStrategyObject, ObservableValue, SubscriptionHandler } from 'mrd-core';

@Component({
    selector: 'mrd-label',
    templateUrl: './mrd-label.component.html',
    styleUrls: ['./mrd-label.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdLabelComponent extends BasePushStrategyObject {

  @Input({transform: booleanAttribute}) public set labelTop(value: boolean) {
    this._labelTop.value = value;
  }
  public get labelTop(): boolean {
    return this._labelTop.value;
  }
  private _labelTop: ObservableValue<boolean> = new ObservableValue(false);

  @Input() public float: 'always' | 'auto' | 'never' = 'auto';
  public floating: ObservableValue<boolean> = new ObservableValue(false);

  public required: ObservableValue<boolean> = new ObservableValue(false);

  constructor(
    protected cdr: ChangeDetectorRef
  ) {
    super();
    this.watch(this.floating.changed, new SubscriptionHandler(() => this.cdr.detectChanges()));
    this.watch(this.required.changed, new SubscriptionHandler(() => this.cdr.detectChanges()));
    this.watch(this._labelTop.changed, new SubscriptionHandler(() => this.cdr.detectChanges()));
  }
}
