import { ConnectedPosition } from '@angular/cdk/overlay';
import { AfterViewInit, Component, ContentChild, ContentChildren, ElementRef, QueryList, ViewChild } from '@angular/core';
import moment, { Moment } from 'moment';
import { ObservableValue, Util } from 'mrd-core';
import { MrdInputComponent } from '../mrd-input/mrd-input.component';

@Component({
    selector: 'mrd-date-range-picker',
    templateUrl: './mrd-date-range-picker.component.html',
    styleUrls: ['./mrd-date-range-picker.component.scss'],
    standalone: false
})
export class MrdDateRangePickerComponent implements AfterViewInit {

  @ContentChildren(MrdInputComponent) public inputs: QueryList<MrdInputComponent>;
  @ViewChild('dateInput') public dateInputElement: ElementRef<HTMLElement>;

  public showDatepicker: ObservableValue<boolean> = new ObservableValue(false);

  public startValue: Moment | null = null;
  public endValue: Moment | null = null;

  public startInput: MrdInputComponent | null = null;
  public endInput: MrdInputComponent | null = null;

  _positions: ConnectedPosition[] = [
        {
          originX: 'start',
          originY: 'bottom',
          overlayX: 'start',
          overlayY: 'top',
        },
        {
          originX: 'end',
          originY: 'bottom',
          overlayX: 'end',
          overlayY: 'top',
        },
        {
          originX: 'start',
          originY: 'top',
          overlayX: 'start',
          overlayY: 'bottom'
        },
        {
          originX: 'end',
          originY: 'top',
          overlayX: 'end',
          overlayY: 'bottom'
        },
      ];


    constructor() {}

    ngAfterViewInit(): void {
      this.startInput = this.inputs.find(input => input.rangeStart);
      this.endInput = this.inputs.find(input => input.rangeEnd);

      if (!this.startInput || !this.endInput) {
        throw new Error('Both start and end inputs must be provided in mrd-date-range-picker');
      }

      this.startValue = moment(this.startInput.formControl.value, 'DD.MM.YYYY').utc(true) || null;
      this.endValue = moment(this.endInput.formControl.value, 'DD.MM.YYYY').utc(true) || null;

      this.startInput.formControl.valueChanges.subscribe(value => {
        this.startValue = value ? moment(value, 'DD.MM.YYYY').utc(true) : null;
      });
      this.endInput.formControl.valueChanges.subscribe(value => {
        this.endValue = value ? moment(value, 'DD.MM.YYYY').utc(true) : null;
      });
    }

    public rangeChanged(value: {start: Moment|null, end: Moment|null}): void {debugger
        this.startValue = value.start;
        this.endValue = value.end;

        if (this.startInput) {
          this.startInput.formControl.setValue(this.startValue);
        }
        if (this.endInput) {
          this.endInput.formControl.setValue(this.endValue);
        }

        if (Util.isDefined(this.startValue) && Util.isDefined(this.endValue)) {
          this.showDatepicker.value = false;
        }
    }
}
