import { AfterViewInit, Component, EventEmitter, Input, Output } from '@angular/core';
import moment, { isMoment, Moment } from 'moment';
import { Util } from 'mrd-core';

@Component({
    selector: 'mrd-timepicker',
    templateUrl: './mrd-timepicker.component.html',
    styleUrls: ['./mrd-timepicker.component.scss'],
    standalone: false
})
export class MrdTimepickerComponent implements AfterViewInit {

  @Input() time: string | Moment | null = null;

  @Output() timeChanged = new EventEmitter<Moment>();

  public hour: number = 0;
  public minute: number = 0;

  public hours: number[] = [];
  public minutes: number[] = [];

  constructor() {
    for (let i = 0; i < 24; i++) {
      this.hours.push(i);
    }
    for (let i = 0; i < 60; i++) {
      this.minutes.push(i);
    }
  }

  ngAfterViewInit(): void {
    this.time = this.checkDate(this.time);
    if (Util.isDefined(this.time) && this.time.isValid()) {
      this.hour = this.time.hour();
      this.minute = this.time.minute();
    }
  }

  private checkDate(timeValue: string|Moment|null): Moment|null {
    if (!Util.isDefined(timeValue)) {
      return null;
    }
    if (!isMoment(timeValue)) {
      timeValue = moment(timeValue, 'HH:mm').year(2020).month(0).day(1).utc(true);
    } else if (!timeValue.isValid()) {
      timeValue = moment().year(2020).month(0).day(1).utc(true);
    } else {
      timeValue = timeValue.clone().year(2020).month(0).day(1).utc(true);
    }
    return timeValue;
  }

  public save(): void {
    const newTime = moment().year(2020).month(0).day(1).hour(this.hour).minute(this.minute).utc(true);
    this.timeChanged.emit(newTime);
  }
}
