import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, Directive, ElementRef, EventEmitter, Host, HostListener, Input, Output, ViewChild, booleanAttribute, numberAttribute } from '@angular/core';
import moment from 'moment';
import { Moment } from 'moment';
import { AccessableFormControl, BaseObject, IValidator, ObservableValue, SubscriptionHandler, Util, ValidatorFloat } from 'mrd-core';
import { ConfigUtil } from '../../../../common/util/config.util';
import { colorAttribute } from '../../../../common/transforms/color-transform';
import * as _ from 'underscore';
import { MrdBaseColorTheme } from '../../../../common/model/config.model';
import { ConnectedPosition } from '@angular/cdk/overlay';


@Component({
    selector: 'mrd-input',
    templateUrl: './mrd-input.component.html',
    styleUrls: ['./mrd-input.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdInputComponent extends BaseObject implements AfterViewInit {

  private static readonly DEFAULT_MAX_LENGTH: number = 512;
  private static readonly DEFAULT_MIN_ROWS: number = 1;
  private static readonly DEFAULT_MAX_ROWS: number = 2;
  private static readonly DEFAULT_LINE_HEIGHT: number = 24;

  private static readonly DATE_REGEX: RegExp = /(\d{2}).(\d{2}).(\d{4})/;
  private static readonly DATE_REGEX_INPUT: RegExp = /(\d{4})-(\d{2})-(\d{2})/;

  @ViewChild('baseInput') public baseInputElement: ElementRef<HTMLInputElement>;
  @ViewChild('textArea') public textAreaElement: ElementRef<HTMLTextAreaElement>;
  @ViewChild('dateInput') public dateInputElement: ElementRef<HTMLInputElement>;
  @ViewChild('timeInput') public timeInputElement: ElementRef<HTMLInputElement>;

  @Input('mrdFormControl') formControl: AccessableFormControl;
  @Input() public placeholder: string = ' ';

  @Input() public value: string = '';

  @Input({transform: numberAttribute}) public maxLength: number;
  @Input({transform: numberAttribute}) public minRows: number = MrdInputComponent.DEFAULT_MIN_ROWS;
  @Input({transform: numberAttribute}) public maxRows: number = MrdInputComponent.DEFAULT_MAX_ROWS;
  @Input({transform: numberAttribute}) public lineHeight: number = MrdInputComponent.DEFAULT_LINE_HEIGHT;

  @Input({transform: booleanAttribute}) public disabled: boolean = false;
  @Input({transform: booleanAttribute}) public readonly: boolean = false;
  @Input({transform: booleanAttribute}) public required: boolean = false;
  @Input({transform: booleanAttribute}) public textarea: boolean = false;
  @Input({transform: booleanAttribute}) public date: boolean = false;
  @Input({transform: booleanAttribute}) public rangeStart: boolean = false;
  @Input({transform: booleanAttribute}) public rangeEnd: boolean = false;
  @Input({transform: booleanAttribute}) public time: boolean = false;

  @Input({transform: booleanAttribute}) public customDateTimeToggle: boolean = false;

  @Input({transform: booleanAttribute}) public validateOnBlur: boolean = false;
  @Input({transform: booleanAttribute}) public formControlChangeOnBlur: boolean = false;

  @Input({transform: colorAttribute}) public set color(value: string) {
    this._color = value;
    this.cdr.markForCheck();
  }
  public get color(): string {
    return this._color;
  }
  private _color: string;

  @Input({alias: 'text-centered', transform: booleanAttribute}) public set centered(value: boolean) {
    this._centered = value;
    this.cdr.markForCheck();
  }
  public get centered(): boolean {
    return this._centered;
  }
  private _centered: boolean = false;

  @Input({alias: 'text-end', transform: booleanAttribute}) public set textEnd(value: boolean) {
    this._textEnd = value;
    this.cdr.markForCheck();
  }
  public get textEnd(): boolean {
    return this._textEnd;
  }
  private _textEnd: boolean = false

  @Input() public datePickerToggle: HTMLElement;

  @Input() public maxDigits: number;

  @Input({transform: booleanAttribute}) public autofocus: boolean = false;

  @Output() touched: EventEmitter<void> = new EventEmitter<void>();
  @Output() focused: EventEmitter<void> = new EventEmitter<void>();
  @Output() blurred: EventEmitter<void> = new EventEmitter<void>();

  @Output() valueChange: EventEmitter<string> = new EventEmitter<string>();
  @Output() inputChange: EventEmitter<string> = new EventEmitter<string>();

  public disabledColor: string = _.isObject(ConfigUtil.getConfig().baseColors.disabled) ? (ConfigUtil.getConfig().baseColors.disabled as MrdBaseColorTheme).text : (ConfigUtil.getConfig().baseColors.disabled as string) || '#afa6a6';
  public labelPresent: boolean = false;
  public isFocused: boolean = false;
  
  public showDatepicker: ObservableValue<boolean> = new ObservableValue<boolean>(false);
  public showTimepicker: ObservableValue<boolean> = new ObservableValue<boolean>(false);

  private formControlChangeValue: any;

  _positions: ConnectedPosition[] = [
      {
        originX: 'start',
        originY: 'bottom',
        overlayX: 'start',
        overlayY: 'top',
      },
      {
        originX: 'end',
        originY: 'bottom',
        overlayX: 'end',
        overlayY: 'top',
      },
      {
        originX: 'start',
        originY: 'top',
        overlayX: 'start',
        overlayY: 'bottom'
      },
      {
        originX: 'end',
        originY: 'top',
        overlayX: 'end',
        overlayY: 'bottom'
      },
    ];

  constructor(
    private cdr: ChangeDetectorRef
  ) {
    super();
  }

  ngAfterViewInit(): void {
    if (Util.isDefined(this.formControl) && this.disabled) {
      throw new Error('Ein deaktiviertes Input kann nicht mit einem FormControl verwendet werden.');
    }

    if (this.maxLength !== undefined && Number.isNaN(this.maxLength)) {
      this.maxLength = MrdInputComponent.DEFAULT_MAX_LENGTH;
    }
    if (this.minRows !== undefined && Number.isNaN(this.minRows)) {
      this.minRows = MrdInputComponent.DEFAULT_MIN_ROWS;
    }
    if (this.maxRows !== undefined && Number.isNaN(this.maxRows)) {
      this.maxRows = MrdInputComponent.DEFAULT_MAX_ROWS;
    }
    if (this.lineHeight !== undefined && Number.isNaN(this.lineHeight)) {
      this.lineHeight = MrdInputComponent.DEFAULT_LINE_HEIGHT;
    }
    if (this.textarea && Util.isDefined(this.textAreaElement) && Util.isDefined(this.maxLength)) {
      this.textAreaElement.nativeElement.maxLength = this.maxLength;
      this.calculateTextAreaHeight();
    }
    this.color = this.color || ConfigUtil.getConfig().formField?.input?.color || '#000000';

    if (this.autofocus) {
      if (this.baseInputElement) {
        this.baseInputElement.nativeElement.focus();
      }
      if (this.textAreaElement) {
        this.textAreaElement.nativeElement.focus();
      }
      if (this.dateInputElement) {
        this.dateInputElement.nativeElement.focus();
      }
      if (this.timeInputElement) {
        this.timeInputElement.nativeElement.focus();
      }
    }

    if (this.date && this.rangeStart) {
      this.textEnd = true;
    }

    if (Util.isDefined(this.formControl) && Util.isDefined(this.formControl.control.value)) {
      this.value = this.formControl.control.value;
      this.cdr.detectChanges();
    }

    if (Util.isDefined(this.formControl)) {
      this.watch(this.formControl.valueChanges, new SubscriptionHandler(() => this.formControlChanged()));
      if (!Util.isDefined(this.maxDigits)) {
        let floatValidator: ValidatorFloat = this.formControl.validators.find((validator: IValidator) => validator instanceof ValidatorFloat) as ValidatorFloat;
        if (Util.isDefined(floatValidator) && Util.isDefined(floatValidator.digitsAfter)) {
          this.maxDigits = floatValidator.digitsAfter;
        }
      }
    }

    this.watch(this.showDatepicker.changed, new SubscriptionHandler((show: boolean) => {
      if (!show) {
        this.isFocused = false;
        this.blurred.emit();
      }
      this.cdr.detectChanges();
    }));
    this.watch(this.showTimepicker.changed, new SubscriptionHandler((show: boolean) => {
      if (!show) {
        this.isFocused = false;
        this.blurred.emit();
      }
      this.cdr.detectChanges();
    }));
  }

  private formControlChanged(): void {
    if (this.textarea) {
      if (Util.isDefined(this.textAreaElement)) {
        this.calculateTextAreaHeight();
      }
    }
    if (Util.isDefined(this.formControl.control.value)) {
      this.value = this.formControl.control.value;
    } else {
      this.value = null;
    }
    this.valueChange.emit(this.value);
    this.cdr.detectChanges();
  }

  public input(event: InputEvent): void {
    let targetValue = (event.target as HTMLInputElement).value;
    if (this.textarea) {
      if (Util.isDefined(this.textAreaElement)) {
        this.calculateTextAreaHeight();
      }
    }

    if (Util.isDefined(this.formControl)) {
      let dateInputMatch = MrdInputComponent.DATE_REGEX_INPUT.test(targetValue);

      if (!this.formControlChangeOnBlur) {
        this.formControl.setValue(targetValue);
      } else {
        this.formControlChangeValue = targetValue;
      }
      
      if (this.date && dateInputMatch) {
        this.baseInputElement.nativeElement.focus();
      }
    } else {
      this.value = targetValue;
      this.valueChange.emit(this.value);
    }

    this.inputChange.emit(targetValue);
    
    this.cdr.detectChanges();
  }

  public dateChanged(event: Moment): void {
    if (Util.isDefined(this.formControl)) {
      if (!this.formControlChangeOnBlur) {
        this.formControl.setValue(event);
        this.baseInputElement.nativeElement.focus();
        this.inputChange.emit(event.format('DD.MM.YYYY'));
      } else {
        this.formControlChangeValue = event;
      }
    } else {
      this.value = event.format('DD.MM.YYYY');
      this.valueChange.emit(this.value);
      this.inputChange.emit(event.format('DD.MM.YYYY'));
    }

    this.showDatepicker.value = false;
    if (this.formControlChangeOnBlur) {
      this.blur(null);
    }
    this.cdr.detectChanges();
  }

  public timeChanged(event: Moment): void {
    if (Util.isDefined(this.formControl)) {
      if (!this.formControlChangeOnBlur) {
        this.formControl.setValue(event);
        this.baseInputElement.nativeElement.focus();
        this.inputChange.emit(event.format('HH:mm'));
      } else {
        this.formControlChangeValue = event;
      }
    } else {
      this.value = event.format('HH:mm');
      this.valueChange.emit(this.value);
      this.inputChange.emit(event.format('HH:mm'));
    }

    this.showTimepicker.value = false;
    if (this.formControlChangeOnBlur) {
      this.blur(null);
    }
    this.cdr.detectChanges();
  }

  private calculateTextAreaHeight(): void {
    this.textAreaElement.nativeElement.style.height = 'auto';
    this.textAreaElement.nativeElement.style.height =
      this.textAreaElement.nativeElement.scrollHeight > (this.maxRows * this.lineHeight) ?
        (this.maxRows * this.lineHeight) + 'px' :
        this.textAreaElement.nativeElement.scrollHeight < (this.minRows * this.lineHeight) ?
        (this.minRows * this.lineHeight) + 'px' :
        this.textAreaElement.nativeElement.scrollHeight + 'px';
  }

  public inputClicked(event: MouseEvent): void {
    this.touched.emit();
  }

  public focus(event: FocusEvent): void {
    this.isFocused = true;
    this.focused.emit();
    this.cdr.detectChanges();
  }

  public blur(event: FocusEvent): void {
    if (this.formControlChangeOnBlur && Util.isDefined(this.formControlChangeValue)) {
      this.formControl.setValue(this.formControlChangeValue);
      let emitValue: any = this.formControlChangeValue;
      if (this.date && moment.isMoment(emitValue)) {
        emitValue = emitValue.format('DD.MM.YYYY');
      }
      if (this.time && moment.isMoment(emitValue)) {
        emitValue = emitValue.format('HH:mm');
      }
      this.inputChange.emit(emitValue);
      this.formControlChangeValue = undefined;
    }
    if (this.formControl && this.date && this.formControl.value && this.formControl.value !== '') {
      if (!moment.isMoment(this.formControl.value)) {
        let momentDate = moment(this.formControl.value, 'DD.MM.YYYY').utc(true);
        if (momentDate.isValid()) {
          this.formControl.setValue(momentDate);
        }
      }
    }
    if (this.formControl && this.time && this.formControl.value && this.formControl.value !== '') {
      if (!moment.isMoment(this.formControl.value)) {
        let momentTime = moment(this.formControl.value, 'HH:mm').year(2020).month(0).day(1).utc(true);
        if (momentTime.isValid()) {
          this.formControl.setValue(momentTime);
        }
      }
    }
    this.isFocused = false;
    this.blurred.emit();
    this.cdr.detectChanges();
  }

  public toggleClicked(): void {
    // this.dateInputElement.nativeElement.showPicker();
    if (this.date) {
      this.showDatepicker.value = !this.showDatepicker.value;
      if (this.showDatepicker.value) {
        this.focus(null);
      }
    }
    if (this.time) {
      this.showTimepicker.value = !this.showTimepicker.value;
      if (this.showTimepicker.value) {
        this.focus(null);
      }
    }
    this.cdr.detectChanges();
  }
}


@Directive({
    selector: '[mrdDateTimePickerToggle]',
    standalone: false
})
export class MrdDatePickerToggle implements AfterViewInit {

  @Input('mrdDateTimePickerToggle') public mrdDateTimePickerToggle: MrdInputComponent;

  constructor(
    private elementRef: ElementRef
  ) {}


  ngAfterViewInit(): void {
    if (this.elementRef.nativeElement.closest('mrd-icon')) {
      this.elementRef.nativeElement.style.cursor = 'pointer';
      this.elementRef.nativeElement.style.width = '20px';
      this.elementRef.nativeElement.style.height = '20px';
    }
  }

  @HostListener('click', ['$event'])
  public onClick(event: MouseEvent): void {
    if (Util.isDefined(this.mrdDateTimePickerToggle)) {
      this.mrdDateTimePickerToggle.toggleClicked();
    }
  }
}