import { Component, EventEmitter, Output } from '@angular/core';

@Component({
    selector: 'mrd-select-custom-trigger',
    templateUrl: './mrd-select-custom-trigger.component.html',
    styleUrls: ['./mrd-select-custom-trigger.component.scss'],
    standalone: false
})
export class MrdSelectCustomTriggerComponent {

  @Output() public triggerClick: EventEmitter<void> = new EventEmitter<void>();

  public triggerClicked(): void {
    this.triggerClick.emit();
  }
}
