import { AfterViewInit, booleanAttribute, ChangeDetectionStrategy, ChangeDetectorRef, Component, ContentChildren, ElementRef, EventEmitter, Input, Output, QueryList, ViewChildren } from '@angular/core';
import { AccessableFormControl, BaseObject, ObservableValue, SubscriptionHandler, Util } from 'mrd-core';
import { MrdTabBodyComponent } from '../../../mrd-tabs/components/mrd-tab-body/mrd-tab-body.component';
import { MrdStepComponent } from '../mrd-step/mrd-step.component';
import { ActivatedRoute, Router } from '@angular/router';
import { MrdTabComponent } from '../../../mrd-tabs/components/mrd-tab/mrd-tab.component';

@Component({
    selector: 'mrd-stepper',
    templateUrl: './mrd-stepper.component.html',
    styleUrls: ['./mrd-stepper.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdStepperComponent extends BaseObject implements AfterViewInit{

  @ContentChildren(MrdStepComponent) steps: QueryList<MrdStepComponent>;
  @ViewChildren(MrdTabBodyComponent) stepBodys: QueryList<MrdTabBodyComponent>;
  @ViewChildren('mrdStepHeader') stepHeader: QueryList<ElementRef>;

  @Input() labelposition: 'top'|'right'|'bottom'|'left' = 'right';

  @Input() public set headerHeight(value: number) {
      this._headerHeight = value;
      this.cdr.detectChanges();
    }
    public get headerHeight(): number {
      return this._headerHeight;
    }
    private _headerHeight: number;
  
    @Input() public set selectedIndex(value: number) {
      this._selectedIndex = value;
      this.activateStep(value);
    }
  
    public get selectedIndex(): number {
      return this._selectedIndex;
    }
    private _selectedIndex: number;

    @Input() public changeStep: ObservableValue<number>;

    @Input({transform: booleanAttribute}) public linear: boolean = false;

    @Output() public selectedStepChanged: EventEmitter<MrdStepComponent> = new EventEmitter();
    @Output() public selectedStepIndexChanged: EventEmitter<number> = new EventEmitter();

    public activeIndex: number;
    private activeStep: MrdStepComponent;
    private activeStepBody: MrdTabBodyComponent;
  
    constructor(
      private cdr: ChangeDetectorRef,
      private router: Router,
      private route: ActivatedRoute
    ) {
      super();
    }

    ngAfterViewInit(): void {
      this.steps.forEach((tab: MrdStepComponent, index: number) => {
        tab.index = index;
      });
  
      if (Util.isDefined(this.changeStep)) {
        this.watch(this.changeStep.changed, new SubscriptionHandler((index: number) => {
          this.activateStep(index);
        }));
        if (Util.isDefined(this.changeStep.value)) {
          this.activateStep(this.changeStep.value);
        }
      }
  
      if (Util.isDefined(this.selectedIndex) && this.selectedIndex !== this.activeIndex) {
        this.activateStep(this.selectedIndex);
      }
  
      // if (this.queryParameterActive) {
      //   this.route.queryParams.subscribe((params) => {
      //     if (Util.isDefined(params[this.queryParameterActive])) {
      //       let index = parseInt(params[this.queryParameterActive]);
      //       if (index >= 0 && index < this.tabs.length) {
      //         this.activateStep(index);
      //       }
      //     } else {
      //       this.activateStep(0);
      //     }
      //   });
      /*} else*/ if (!Util.isDefined(this.activeIndex)) {
        this.activateStep(0);
      }
  
      
    }
  
    public activateStep(index: number): void {
      if (this.linear && Util.isDefined(this.activeStep) && index > this.activeIndex && !this.activeStep.valid) {
        return;
      }
      if (Util.isDefined(this.activeIndex) && Util.isDefined(this.activeStep)) {
        if (index === this.activeIndex) {
          return;
        }
        if (index > this.activeIndex) {
          this.activeStepBody.translate = -100;
          this.activeStep.active = false;
        }
        if (index < this.activeIndex) {
          this.activeStepBody.translate = 100;
          this.activeStep.active = false;
        }
      }
  
      if (Util.isDefined(this.stepBodys)) {
        this.stepBodys.forEach((tab: MrdTabBodyComponent, i: number) => {
          if (i < index) {
            tab.translate = -100;
          }
          if (i > index) {
            tab.translate = 100;
          }
        });
  
        let tabBody = this.stepBodys.get(index);
        let tab = this.steps.get(index);
  
        // Frag mich nicht wieso, aber wenn die Tabs nicht über die Standard-Header, sondern über
        // selectedIndex oder changeTab gesetzt werden, dann ist der Content des TabBodys manchmal destroyed.
        // Deshalb setzen wir ihn hier wieder auf den Content des Tabs, der immer funktioniert.
        if (!tabBody.content || tabBody.content.destroyed) {
          tabBody.content = tab.content;
        }
  
        tab.active = true;
        tabBody.translate = 0;
        this.activeIndex = index;
        this.activeStepBody = tabBody;
        this.activeStep = tab;
  
        // if (this.queryParameterActive) {
        //   this.router.navigate([], {
        //     queryParams: {
        //       [this.queryParameterActive]: index
        //     },
        //     queryParamsHandling: 'merge'
        //   });
        // }
  
        // if (!this.noHeader) {
          // let header = this.stepHeader.get(index);
        // }

        this.selectedStepChanged.emit(tab);
        this.selectedStepIndexChanged.emit(index);
      }
      this.cdr.detectChanges();
    }
}
