import { AfterViewInit, ChangeDetectionStrategy, ChangeDetectorRef, Component, ElementRef, Input, ViewChild, numberAttribute } from '@angular/core';
import { Util } from 'mrd-core';

@Component({
    selector: 'mrd-hint',
    templateUrl: './mrd-hint.component.html',
    styleUrls: ['./mrd-hint.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
    standalone: false
})
export class MrdHintComponent implements AfterViewInit {

  @ViewChild('hintContent') hintContent: ElementRef;

  @Input({transform: numberAttribute}) public ellipsis: number;

  public tootltipText: string = '';

  constructor(
    private cdr: ChangeDetectorRef
  ) { }

  ngAfterViewInit(): void {
    if (Util.isDefined(this.hintContent) && Util.isDefined(this.hintContent.nativeElement) && Util.isDefined(this.hintContent.nativeElement.innerText)) {
      this.tootltipText = this.hintContent.nativeElement.innerText;
    }

    if (this.ellipsis !== undefined && Number.isNaN(this.ellipsis)) {
      this.ellipsis = 1;
    }
    this.cdr.detectChanges();
  }
}
