import { ChangeDetectionStrategy, ChangeDetectorRef, Component,  ContentChild,  Directive,  EmbeddedViewRef, Input, TemplateRef, ViewChild, ViewRef } from '@angular/core';
import { AccessableFormControl } from 'mrd-core';

@Directive({
    selector: '[mrdStep]',
    standalone: false
})
export class MrdStepComponent {

  @ViewChild(TemplateRef, {static: true}) _implicitContent: TemplateRef<any>;

  @Input('mrdStep') public set label(value: string) {
    this._label = value;
  }
  public get label(): string {
    return this._label;
  }
  private _label: string;

  @Input() public mrdStepControl: AccessableFormControl;

  private _embeddedViewRef: EmbeddedViewRef<any> | null = null;

  get content(): ViewRef | null {
    if (!this._embeddedViewRef || this._embeddedViewRef.destroyed) {
      this._embeddedViewRef = this.tr.createEmbeddedView({ $implicit: 'Angular', dateNow: new Date() });
    }
    return this._embeddedViewRef;
  }

  /**
   * Zero based index of the step
   *
   * @memberof MrdStepComponent
   */
  public set index(value: number) {
    this._index = value;
    this.cdr.detectChanges();
  }
  public get index(): number {
    return this._index;
  }
  private _index: number;

  public set active(value: boolean) {
    if (this._active && !value) {
      this._touched = true;
    }
    this._active = value;
    this.cdr.detectChanges();
  }
  public get active(): boolean {
    return this._active;
  }
  private _active: boolean;

  // @Input({alias: 'mrdTabPreserveContent',transform: booleanAttribute}) public preserveContent: boolean = false;

  public get valid(): boolean {
    return !this.mrdStepControl || this.mrdStepControl.valid;
  }

  public get touched(): boolean {
    return this._touched;
  }
  private _touched: boolean = false;

  constructor(
    private cdr: ChangeDetectorRef,
    readonly tr: TemplateRef<any>
  ) {}
}
